import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const SCREENS = ["Нүүр", "Ангилал", "Тухай"];

function App() {
  const [screen, setScreen] = useState("Нүүр");
  return (
    <View style={styles.container}>
      <View style={styles.segs}>
        {SCREENS.map((s, i) => (
          <Pressable key={s} nativeID={"seg" + i} onPress={() => setScreen(s)}
            style={styles.seg}>
            {/* энд бичнэ үү: идэвхтэй дэлгэц бол styles.active нэм */}
            <Text style={styles.segText}>{s}</Text>
          </Pressable>
        ))}
      </View>
      <Text nativeID="body" style={styles.body}>{screen} дэлгэц</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16, gap: 16 },
  segs: { flexDirection: "row", gap: 8 },
  seg: { flexGrow: 1, padding: 12, borderRadius: 10, borderWidth: 1, borderColor: "#cbd5e1", alignItems: "center" },
  active: { backgroundColor: "#2563eb", borderColor: "#2563eb" },
  segText: { fontWeight: "600" },
  body: { fontSize: 20, fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const SCREENS = ["Нүүр", "Ангилал", "Тухай"];

function App() {
  const [screen, setScreen] = useState("Нүүр");
  return (
    <View style={styles.container}>
      <View style={styles.segs}>
        {SCREENS.map((s, i) => (
          <Pressable key={s} nativeID={"seg" + i} onPress={() => setScreen(s)}
            style={[styles.seg, screen === s && styles.active]}>
            <Text style={styles.segText}>{s}</Text>
          </Pressable>
        ))}
      </View>
      <Text nativeID="body" style={styles.body}>{screen} дэлгэц</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16, gap: 16 },
  segs: { flexDirection: "row", gap: 8 },
  seg: { flexGrow: 1, padding: 12, borderRadius: 10, borderWidth: 1, borderColor: "#cbd5e1", alignItems: "center" },
  active: { backgroundColor: "#2563eb", borderColor: "#2563eb" },
  segText: { fontWeight: "600" },
  body: { fontSize: 20, fontWeight: "bold" },
});

registerRootComponent(App);
